import{_ as a,o as n,c as d,a2 as e}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"2.2 电路的组成","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-2-dian-lu-de-zu-cheng.md","filePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-2-dian-lu-de-zu-cheng.md","lastUpdated":1793095197000}'),s={name:"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-2-dian-lu-de-zu-cheng.md"};function o(r,t,l,i,h,c){return n(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="_2-2-电路的组成" tabindex="-1">2.2 电路的组成 <a class="header-anchor" href="#_2-2-电路的组成" aria-label="Permalink to &quot;2.2 电路的组成&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>你已经认识了电流、电压、电阻三个&quot;主角&quot;,这一节看它们怎么凑成一台戏——<strong>一个完整的电路由哪些部分组成</strong>,电路有哪几种&quot;状态&quot;,以及怎么用电路图符号把它画出来。</p><h2 id="一、什么是电路" tabindex="-1">一、什么是电路 <a class="header-anchor" href="#一、什么是电路" aria-label="Permalink to &quot;一、什么是电路&quot;">​</a></h2><p><strong>电路</strong>,就是<strong>电流流通的路径</strong>。最简单理解:把电源、用电器、导线接起来,电流从电源的一端出发,经过用电器,再回到电源的另一端,形成一个闭合的回路。</p><h2 id="二、电路的四大基本组成" tabindex="-1">二、电路的四大基本组成 <a class="header-anchor" href="#二、电路的四大基本组成" aria-label="Permalink to &quot;二、电路的四大基本组成&quot;">​</a></h2><p>一个最简单的电路,至少要有四样东西:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      ┌─────────────┐</span></span>
<span class="line"><span>      │    电源      │  ← 提供电压(推动力)</span></span>
<span class="line"><span>      └──────┬──────┘</span></span>
<span class="line"><span>             │ 导线</span></span>
<span class="line"><span>        ┌────┴────┐</span></span>
<span class="line"><span>        │  开关    │  ← 控制电路通断</span></span>
<span class="line"><span>        └────┬────┘</span></span>
<span class="line"><span>             │ 导线</span></span>
<span class="line"><span>      ┌──────┴──────┐</span></span>
<span class="line"><span>      │    负载     │  ← 消耗电能,把电能转成其他能量</span></span>
<span class="line"><span>      └─────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>组成</th><th>作用</th><th>例子</th></tr></thead><tbody><tr><td><strong>电源</strong></td><td>提供电压,把其他能量转成电能</td><td>电池、发电机、配电变压器</td></tr><tr><td><strong>负载(用电设备)</strong></td><td>消耗电能,把电能转成其他能量</td><td>灯泡、电动机、电炉</td></tr><tr><td><strong>导线</strong></td><td>连接各元件,让电流流通</td><td>铜线、电缆</td></tr><tr><td><strong>开关(含保护装置)</strong></td><td>控制电路的通断、保护电路</td><td>刀开关、断路器、熔断器</td></tr></tbody></table><blockquote><p>💡 <strong>水流类比</strong>:电源=水泵(提供压力),导线=水管,开关=阀门,负载=水轮机(消耗水流做功)。水泵不给力(电压低)、阀门关着(断开)、水管漏了(短路),水轮机都转不起来。</p></blockquote><h2 id="三、电路的三种状态" tabindex="-1">三、电路的三种状态 <a class="header-anchor" href="#三、电路的三种状态" aria-label="Permalink to &quot;三、电路的三种状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>后果/特点</th></tr></thead><tbody><tr><td><strong>通路(闭路)</strong></td><td>电路处处接通,电流流通</td><td>正常工作,负载做功</td></tr><tr><td><strong>断路(开路)</strong></td><td>某处断开,电流无法流通</td><td>电路无电流,负载不工作</td></tr><tr><td><strong>短路</strong></td><td>电源两端被直接接通,中间几乎无负载</td><td><strong>电流极大,烧坏设备、引发火灾</strong>,必须防止</td></tr></tbody></table><blockquote><p>⚠️ <strong>短路是电工大忌</strong>:短路时电流不经过(或只经过很小)负载,直接构成低阻回路,电流瞬间飙升,产生大量热量,烧毁导线和设备,甚至引发火灾和爆炸。所以低压电器里专门有&quot;短路保护&quot;(熔断器、断路器)——第 5 章会讲。</p></blockquote><h2 id="四、电路图与常用符号" tabindex="-1">四、电路图与常用符号 <a class="header-anchor" href="#四、电路图与常用符号" aria-label="Permalink to &quot;四、电路图与常用符号&quot;">​</a></h2><p><strong>电路图</strong>是用规定的符号表示电路连接关系的图,电工必须看得懂、画得对。几个最常用的符号先认识:</p><table tabindex="0"><thead><tr><th>元件</th><th>图形符号</th><th>文字符号</th></tr></thead><tbody><tr><td>电池(电源)</td><td>\`—</td><td></td></tr><tr><td>灯泡</td><td><code>—ⓧ—</code></td><td>EL</td></tr><tr><td>电阻</td><td><code>—▭▭—</code></td><td>R</td></tr><tr><td>开关</td><td><code>—/——</code></td><td>S 或 SA</td></tr><tr><td>导线</td><td><code>———</code></td><td>L(火线)/N(零线)</td></tr><tr><td>熔断器</td><td><code>—☒—</code></td><td>FU</td></tr><tr><td>电动机</td><td><code>M</code>(圆圈内)</td><td>M</td></tr></tbody></table><blockquote><p>💡 完整系统的图形符号、文字符号识别,在第 9.4 节&quot;电工识图基础&quot;详细展开,这里先混个脸熟。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 电路四大组成:<strong>电源、负载、导线、开关(保护装置)</strong>——缺一不可(考试常考&quot;下列哪个不是电路的必要组成部分&quot;)。</li><li>✅ 短路 = 电流不经过负载直接连通电源两端,<strong>电流极大</strong>,必须严防。</li><li>✅ 断路 = 电路断开,无电流、负载不工作。</li><li>⚠️ 易混点:短路和断路是两个相反的概念,别搞反。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>电路是电流流通的路径,由电源、负载、导线、开关四要素组成。</li><li>三种状态:通路(工作)、断路(不工作)、短路(危险)。</li><li>短路电流极大,是电气火灾的主要原因之一。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)电路的基本组成部分不包括()。 A. 电源　B. 负载　C. 仪表　D. 导线</li><li>(判断)短路时电路中的电流会急剧增大,可能烧毁设备和引发火灾。( )</li><li>(单选)当电路某处断开,电流无法流通,这种状态称为()。 A. 通路　B. 短路　C. 断路　D. 过载</li><li>(判断)开关的作用是控制电路的通断。( )</li><li>(单选)把电源的正负极用导线直接连通,中间没有负载,这种情况属于()。 A. 断路　B. 短路　C. 正常通路　D. 过载运行</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>C</strong>。电路的四个基本部分是电源、负载、导线、开关(保护装置),仪表不是必需组成。</li><li><strong>√</strong>。短路电流极大,发热量巨大,是火灾的重要原因。</li><li><strong>C</strong>。断开无电流 = 断路。</li><li><strong>√</strong>。开关的作用就是接通或断开电路。</li><li><strong>B</strong>。不经负载直接连通电源两端就是短路,很危险。</li></ol></details>`,24)])])}const u=a(s,[["render",o]]);export{g as __pageData,u as default};
